package edu.northeastern.cs6510.selfcheckout.contract;
import edu.northeastern.cs6510.selfcheckout.api.*; import edu.northeastern.cs6510.selfcheckout.transaction.*; import java.time.Instant; import java.util.Map; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.test.web.servlet.MockMvc; import static org.mockito.Mockito.when; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(TransactionController.class) class GetTransactionContractTest { @Autowired MockMvc mvc; @MockBean TransactionService service; @Test void returnsTransactionOrNotFound() throws Exception { when(service.get("tx-1")).thenReturn(new Transaction("tx-1","station-1",TransactionStatus.OPEN,Map.of(),Map.of(),0,0,Instant.now(),null)); mvc.perform(get("/transactions/tx-1")).andExpect(status().isOk()).andExpect(jsonPath("$.transactionId").value("tx-1")); when(service.get("missing")).thenThrow(ApiException.transactionNotFound("missing")); mvc.perform(get("/transactions/missing")).andExpect(status().isNotFound()).andExpect(jsonPath("$.error").value("TRANSACTION_NOT_FOUND")); } }
